function et_export($path,$title,$nodes,$page=false){global $homePhotoVariable;if($page){$seen=false;foreach($nodes as &$node){if(str_contains($node['settings']['custom_css']??'',$homePhotoVariable)){if($seen)$node['settings']['custom_css']=str_replace($homePhotoVariable,'',$node['settings']['custom_css']);$seen=true;}}unset($node);}$doc=['version'=>'0.4','title'=>$title,'type'=>$page?'page':'section','content'=>$nodes,'page_settings'=>['hide_title'=>'yes']];file_put_contents($path,wp_json_encode($doc,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES|JSON_PRETTY_PRINT)."\n");}
