$manifest=[];foreach(['home'=>$home,'about'=>$about] as $key=>$sections){if(!is_dir($out.'/'.$key))mkdir($out.'/'.$key,0775,true);$full=[];foreach($sections as $name=>$data){$nodes=et_nodes($data);$full=array_merge($full,$nodes);$title=($key==='home'?'صفحه اصلی':'معرفی مدرسه').' — '.$labels[$key][$name];et_export($out.'/'.$key.'/'.$name.'.json',$title,$nodes);$manifest[$key][]=$name.'.json';}et_export($out.'/'.$key.'-complete.json',$key==='home'?'دانشگران — صفحه اصلی کامل':'دانشگران — معرفی مدرسه کامل',$full,true);}
// Extra individual news blocks for independent placement.
foreach(['school'=>false,'ministry'=>true] as $key=>$ministry)et_export($out.'/home/05-news-'.$key.'.json','اخبار — '.$key,[et_section([et_col(et_news_widgets($ministry))],'det-news-'.$key,$newsCss)]);
file_put_contents($out.'/manifest.json',wp_json_encode(['requires'=>['Elementor Pro','Daneshgaran School >= 0.19.0'],'pages'=>$manifest,'automatic_changes'=>false],JSON_PRETTY_PRINT|JSON_UNESCAPED_SLASHES));
echo 'Exported templates to '.$out."\n";
